/* GENERATED by gen_hcon_vault.py -- models are generated.
   HUB_CASE : 7 feed(s) over 7 source view(s), 3 run(s): opus_health_delta3, opus_health_legacy_v4, opus_health_v2
   LOADER SHAPE: ONE loader for this vault table; each run is a SEPARATE feed
   tagged by RECORD_SOURCE and SOURCE_RUN. RECORD_SOURCE is NEVER in the key.
   KEY FORM: md5(upper('HUB_CASE|' || <business key>)), emitted EXPLICITLY -- no macro computes a
   hash in this build. The namespace is a MEASURED collision guard: opus_health_v2 emits
   md5(upper(HUB_ASSESSMENT_BK__SCRUTINY_NO)) AND md5(upper(HUB_PROPOSAL_BK__SCRUTINY_NO)),
   the same column under two hubs, which collide without it; legacy namespaces 1822 of 1822.
   CRITICAL PRECISION: the namespace separates HUBS, NOT REGISTRIES WITHIN A HUB.
   'HUB_POLICY|' prefixes POLICY_REF and POLICY_NO identically, so it does nothing to keep
   two identifier populations inside one hub apart.
   REGISTRY RECONCILIATION, UNRESOLVED: unifying the hash form does NOT establish that the
   two runs' identifier spaces denote the same entities. 6 of the 14 shared hubs have ZERO
   business-key-column overlap between the runs. This hub is ONE KEY SPACE over the
   registries enumerated below; a false merge is unrecoverable after load.
     opus_health_delta3       1 registry/registries: HUB_CASE_BK__INWARDNO
     opus_health_legacy_v4    5 registry/registries: HUB_CASE_BK__ALLOCATE_ID, HUB_CASE_BK__ENHANCE_REF_ID, HUB_CASE_BK__ITRACK_NO, HUB_CASE_BK__QUERY_REF_ID, HUB_CASE_BK__REQUEST_NO
     opus_health_v2           1 registry/registries: HUB_CASE_BK__CASHLESS_IN_ID
*/

with feeds as (
    select HUB_CASE_HK, HUB_CASE_BK__ITRACK_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_case__hm_hat_itrack_dtls__d5089133fe') }}
    union all
    select HUB_CASE_HK, HUB_CASE_BK__ALLOCATE_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_case__hm_inward_autoallocation__8952eecd65') }}
    union all
    select HUB_CASE_HK, HUB_CASE_BK__CASHLESS_IN_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_case__hm_inward_omni_mapping__797cd6e2ab') }}
    union all
    select HUB_CASE_HK, HUB_CASE_BK__ENHANCE_REF_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_case__hm_preauth_enhance__d297ccc4d5') }}
    union all
    select HUB_CASE_HK, HUB_CASE_BK__QUERY_REF_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_case__hm_preauth_query__02facaa54f') }}
    union all
    select HUB_CASE_HK, HUB_CASE_BK__REQUEST_NO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_case__scr_hlth_portable_dtls__d972ff3e8a') }}
    union all
    select HUB_CASE_HK, HUB_CASE_BK__INWARDNO as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_case__ng_fax_inward_details__f69ec9b313') }}
)

select
    HUB_CASE_HK,
    BUSINESS_KEY,
    min(RECORD_SOURCE) as RECORD_SOURCE,
    min(SOURCE_RUN) as SOURCE_RUN,
    min(LOAD_DATETIME) as LOAD_DATETIME
from feeds
where HUB_CASE_HK is not null
group by HUB_CASE_HK, BUSINESS_KEY
